import Vue from 'vue'
import VueRouter from 'vue-router'
import RecruitmentPage from '../views/RecruitmentPage.vue'
import RecruitmentInfoPage from '../views/RecruitmentInfoPage.vue'
import HomePage from '../views/HomePage.vue'
// 导入 AboutPage 组件
// 移除这一行
// import AboutPage from '../views/AboutPage.vue'

Vue.use(VueRouter)

const routes = [
  {
    path: '/',
    redirect: '/home'  // 将根路径重定向到/home
  },
  {
    path: '/home',
    name: 'Home',
    component: () => import('../views/HomePage.vue')
  },
  // 移除或注释掉 About 路由
  // {
  //   path: '/about',
  //   name: 'About',
  //   component: AboutPage
  // },
  {
    path: '/admission',
    name: 'Admission',
    component: RecruitmentPage,
    props: { activeTab: 'admission' }
  },
  {
    path: '/recruitment',
    name: 'Recruitment',
    component: RecruitmentPage,
    props: { activeTab: 'recruitment' }
  },
  {
    path: '/recruitment-info',
    name: 'RecruitmentInfo',
    component: RecruitmentInfoPage
  },
  {
    path: '/registration',
    name: 'Registration',
    component: RecruitmentPage,
    props: { activeTab: 'registration' }
  },
  {
    path: '/contact',
    name: 'Contact',
    component: RecruitmentPage,
    props: { activeTab: 'contact' }
  }
  // 如果 bm-school-vue 中有其他路由，也需要在这里添加
]

const router = new VueRouter({
  mode: 'history',
  base: process.env.BASE_URL,
  routes
})

export default router
